1	// Acceptance tests for the change request:
2	//   "On the home screen show me my top five clients. Rank them by how much they owe."
3	//
4	// The home screen is the dashboard (dashboard.spec.ts: it is reached from the nav via nav-dashboard
5	// and renders dashboard-page). This change adds a TOP-CLIENTS panel to it (dashboard-top-clients,
6	// with its own dashboard-top-clients-loading / dashboard-top-clients-error states — it queries for
7	// itself, like the overdue tile in dashboard-overdue.spec.ts). The panel lists AT MOST FIVE clients,
8	// the ones who owe the most, ranked by HOW MUCH THEY OWE, most first. Each row
9	// (top-client-row-<clientId>) shows that client's NAME (top-client-name) and the amount they owe
10	// (top-client-amount).
11	//
12	// "How much a client owes" carries the app's established owed meaning (client-statement.spec.ts's
13	// client-outstanding-total, invoice-owed-sent-only.spec.ts, discount-owed.spec.ts): the sum, across
14	// ALL of that client's invoices, of each SENT-but-unpaid invoice's REMAINING balance — the invoice's
15	// (discounted) total minus what has been paid on it. A DRAFT has not gone out, so it is not yet owed;
16	// a PAID invoice is already in, so it adds nothing. So a client's owed figure is NOT their total
17	// billed and NOT their total ignoring payments or stage — the fixtures below make those wrong
18	// readings produce a visibly different ranking.
19	//
20	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
21	// clients { id, name, email }, projects { id, clientId, name }, invoices { id, projectId, amount,
22	// status } and payments { id, invoiceId, amount, date }. This change introduces NO new audit record,
23	// so nothing is asserted through the audit channel.
24	//
25	// top-client-amount is a NEW money anchor (not one of the three money-format.spec.ts pins exactly),
26	// so it is matched leniently the way the sibling new money anchors are — a leading "$" and a trailing
27	// ".00" both optional. All owed figures are kept under a thousand so the thousands separator
28	// (money-thousands-separator.spec.ts) is not in play. Amounts and names are chosen so that every
29	// plausible WRONG ranking (by total billed, ignoring payments, or counting drafts / paid invoices)
30	// pulls a different set of clients into the top five and/or a different order, so each assertion
31	// pins the sent-and-net-of-payments reading specifically. This SHOULD FAIL before the change: there
32	// is no top-clients panel on the dashboard today.
33	import { test, expect, type Page } from '@playwright/test';
34	import { resetAndSeed } from '../support/seed';
35	
36	// "$500.00", "500.00" or "500" all pass — the "$" and the ".00" cents are both optional, exactly as
37	// the other NEW money anchors (statement / invoice-due) are matched; exact presentation is pinned
38	// elsewhere by money-format.spec.ts.
39	function money(amount: number): RegExp {
40	  return new RegExp(`^\\$?${amount}(\\.00)?$`);
41	}
42	
43	// Reach the home screen (the dashboard) through its nav link — the nav entry is the stable contract
44	// (nav-dashboard), the concrete path is the feature's own choice — and wait for the top-clients
45	// panel's OWN data to settle (it queries for itself).
46	async function openTopClients(page: Page) {
47	  await page.goto('/');
48	  await expect(page.getByTestId('app-root')).toBeVisible();
49	  await page.getByTestId('nav-dashboard').click();
50	  await expect(page.getByTestId('dashboard-page')).toBeVisible();
51	
52	  await expect(page.getByTestId('dashboard-top-clients')).toBeVisible();
53	  await expect(page.getByTestId('dashboard-top-clients-loading')).toHaveCount(0);
54	  await expect(page.getByTestId('dashboard-top-clients-error')).toHaveCount(0);
55	  return page.getByTestId('dashboard-top-clients');
56	}
57	
58	test.describe('home screen: top five clients ranked by how much they owe', () => {
59	  test('shows the five biggest debtors, most owed first, and no one else', async ({ page }) => {
60	    await resetAndSeed({
61	      clients: [
62	        { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
63	        { id: 2, name: 'Globex', email: 'hello@globex.example' },
64	        { id: 3, name: 'Initech', email: 'info@initech.example' },
65	        { id: 4, name: 'Umbrella', email: 'contact@umbrella.example' },
66	        { id: 5, name: 'Stark Industries', email: 'hi@stark.example' },
67	        { id: 6, name: 'Wayne Enterprises', email: 'ops@wayne.example' },
68	        { id: 7, name: 'Hooli', email: 'hello@hooli.example' },
69	      ],
70	      projects: [
71	        { id: 1, clientId: 1, name: 'Acme site' },
72	        { id: 2, clientId: 2, name: 'Globex site' },
73	        { id: 3, clientId: 3, name: 'Initech site' },
74	        { id: 4, clientId: 4, name: 'Umbrella site' },
75	        { id: 5, clientId: 5, name: 'Stark site' },
76	        { id: 6, clientId: 6, name: 'Wayne site' },
77	        { id: 7, clientId: 7, name: 'Hooli site' },
78	      ],
79	      invoices: [
80	        // Acme owes 500 (sent, nothing paid) — the most. #1.
81	        { id: 1, projectId: 1, amount: 500, status: 'SENT' },
