1	// Acceptance tests for the change request:
2	//   "For bigger amounts put commas in. Show it like $1,234.50. Do this everywhere an amount shows,
3	//    including on the invoices and on the client statement."
4	//
5	// The app already renders money with a dollar sign and two decimal places (see money-format.spec.ts,
6	// which pins "$120.00" / "$99.50" / "$0.00" for amounts below a thousand — those stay exactly as
7	// they are). This change adds a THOUSANDS SEPARATOR: once an amount reaches a thousand it is grouped
8	// with commas, so 1234.50 shows as "$1,234.50" and a million shows as "$1,000,000.00" (two commas).
9	// Because money is formatted the same way everywhere, this must hold wherever an amount is surfaced;
10	// the request calls out the invoices and the client statement by name, so those are what this spec
11	// pins — exactly, with toHaveText, including the commas.
12	//
13	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
14	// clients { id, name, email }, projects { id, clientId, name }, invoices { id, projectId, amount,
15	// status } and payments { id, invoiceId, amount, date }. No audit record is involved.
16	//
17	// Amounts are chosen so every asserted value is at or above a thousand and so carries a comma, and so
18	// that no two expected strings collide. Against the app BEFORE this change (a bare "$1234.50" with no
19	// comma) every assertion here fails, which is expected.
20	import { test, expect } from '@playwright/test';
21	import { resetAndSeed } from '../support/seed';
22	
23	test.describe('bigger amounts are grouped with commas, like $1,234.50', () => {
24	  test("a project's invoice amounts and their total carry thousands commas", async ({ page }) => {
25	    await resetAndSeed({
26	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
27	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
28	      invoices: [
29	        // A four-figure amount with cents -> one comma: $1,234.50 (the example from the request).
30	        { id: 1, projectId: 1, amount: 1234.5, status: 'SENT' },
31	        // A seven-figure amount -> two commas, cents still padded: $1,000,000.00.
32	        { id: 2, projectId: 1, amount: 1000000, status: 'SENT' },
33	      ],
34	    });
35	
36	    await page.goto('/projects');
37	    await page.getByTestId('project-open-1').click();
38	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
39	
40	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toHaveText('$1,234.50');
41	    await expect(page.getByTestId('invoice-row-2').getByTestId('invoice-amount')).toHaveText('$1,000,000.00');
42	
43	    // The invoices total (1234.50 + 1,000,000 = 1,001,234.50) is money too, grouped the same way.
44	    await expect(page.getByTestId('project-invoices-total')).toHaveText('$1,001,234.50');
45	  });
46	
47	  test('the all-invoices list groups each amount with commas', async ({ page }) => {
48	    await resetAndSeed({
49	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
50	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
51	      invoices: [
52	        { id: 1, projectId: 1, amount: 2500, status: 'SENT' },
53	        { id: 2, projectId: 1, amount: 12345.67, status: 'SENT' },
54	      ],
55	    });
56	
57	    await page.goto('/invoices');
58	    await expect(page.getByTestId('all-invoices-table')).toBeVisible();
59	
60	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toHaveText('$2,500.00');
61	    await expect(page.getByTestId('invoice-row-2').getByTestId('invoice-amount')).toHaveText('$12,345.67');
62	  });
63	
64	  test('the client statement groups amount, paid, due and the owed total with commas', async ({ page }) => {
65	    await resetAndSeed({
66	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
67	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
68	      invoices: [
69	        // 5234.50 billed, 1234.50 paid -> 4000.00 still due; still SENT (part paid, counts toward owed).
70	        { id: 1, projectId: 1, amount: 5234.5, status: 'SENT' },
71	        // 2500 billed, nothing paid -> 2500.00 still due.
72	        { id: 2, projectId: 1, amount: 2500, status: 'SENT' },
73	      ],
74	      payments: [{ id: 1, invoiceId: 1, amount: 1234.5, date: '2025-06-15' }],
75	    });
76	
77	    await page.goto('/clients');
78	    await page.getByTestId('client-open-1').click();
79	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
80	    await page.getByTestId('client-statement-open').click();
81	    await expect(page.getByTestId('client-statement')).toBeVisible();
82	    await expect(page.getByTestId('client-statement-table')).toBeVisible();
83	
84	    // Invoice 1: billed $5,234.50, paid $1,234.50, due $4,000.00 — every money cell grouped.
85	    const row1 = page.getByTestId('statement-invoice-row-1');
86	    await expect(row1.getByTestId('statement-invoice-amount')).toHaveText('$5,234.50');
87	    await expect(row1.getByTestId('statement-invoice-paid')).toHaveText('$1,234.50');
88	    await expect(row1.getByTestId('statement-invoice-due')).toHaveText('$4,000.00');
